import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a unique file inside {@code dir} using {@code name}.  
     * The method protects against directory‑traversal attacks by ensuring that the
     * resolved path stays within {@code dir}. It also strips query parameters
     * from the supplied name and guarantees that the resulting file does not
     * overwrite an existing one by appending a numeric suffix if necessary.
     *
     * @param dir  the target directory (must not be {@code null})
     * @param name the desired file name (may contain a query string)
     * @return a {@link File} instance pointing to a non‑existing file inside {@code dir}
     * @throws IllegalArgumentException if {@code dir} or {@code name} is {@code null},
     *                                  or if the resolved path escapes {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Target directory cannot be null");
        }
        if (name == null) {
            throw new IllegalArgumentException("File name cannot be null");
        }

        // Remove query parameters if present
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Resolve the requested path against the target directory and normalize it
        Path dirPath = dir.toPath().normalize();
        Path targetPath = dirPath.resolve(name).normalize();

        // Ensure the resolved path is still within the target directory
        if (!targetPath.startsWith(dirPath)) {
            throw new IllegalArgumentException(
                "Attempted to create a file outside the target directory: " + name);
        }

        File file = targetPath.toFile();

        // If a file with the same name already exists, append a numeric suffix
        int dot = name.lastIndexOf('.');
        String prefix = dot < 0 ? name : name.substring(0, dot);
        String suffix = dot < 0 ? "" : name.substring(dot);
        int index = 2;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
        }

        // Create any missing parent directories
        File parent = file.getParentFile();
        if (parent != null && !parent.exists()) {
            parent.mkdirs();
        }

        return file;
    }

    // other methods
}
