import static java.util.Calendar.*;

public final class CronTab {

    // other methods

    /**
     * Safely sets the specified calendar field to the desired value.
     *
     * <p>Historically this method performed a simple {@code c.set(field, i - offset)}.
     * When {@code i} fell outside the valid range for the field, {@link Calendar}
     * would silently adjust adjacent fields, potentially creating an endless
     * adjustment loop in {@link #ceil}.  To prevent this, the value is now
     * clamped to the field’s actual minimum and maximum before being set.</p>
     *
     * @param c the calendar to modify – must not be {@code null}
     * @param i the raw value supplied by the caller
     * @throws IllegalArgumentException if {@code c} is {@code null}
     */
    void setTo(Calendar c, int i) {
        if (c == null) {
            throw new IllegalArgumentException("Calendar cannot be null");
        }

        // Compute the intended value accounting for the field‑specific offset.
        int value = i - offset;

        // Retrieve the legal bounds for this field in the current calendar context.
        int min = c.getActualMinimum(field);
        int max = c.getActualMaximum(field);

        // Clamp the value to avoid overflow/underflow that could trigger
        // cascading adjustments and infinite loops.
        if (value < min) {
            value = min;
        } else if (value > max) {
            value = max;
        }

        // Apply the validated value.
        c.set(field, value);
