    protected void extractFile(final File srcF,
                               final File dir,
                               final InputStream compressedInputStream,
                               final String entryName,
                               final Date entryDate,
                               final boolean isDirectory,
                               final Integer mode,
                               String symlinkDestination) throws IOException, ArchiverException {

