public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate {

    // other methods

    /**
     * Validates a media type component (major or subtype).
     *
     * <p>The method accepts either the wildcard "*" or a token that conforms to RFC 7230
     * § 3.2.6. A token consists of one or more of the following characters:
     * {@code !#$%&'*+-.^_`|~0-9A-Za-z}.  All other characters, including control
     * characters, whitespace, and line terminators, are rejected to prevent HTTP
     * header injection.</p>
     *
     * @param str the component to validate
     * @return {@code true} if {@code str} is a valid token or "*", {@code false} otherwise
     */
    protected static boolean isValid(String str) {
        if (str == null || str.isEmpty()) {
            return false;
        }
        // Allow the wildcard character
        if ("*".equals(str)) {
            return true;
        }
        // RFC 7230 token characters
        // tchar = "!" / "#" / "$" / "%" / "&" / "'" / "*" / "+" / "-" / "." /
        //        "^" / "_" / "`" / "|" / "~" / DIGIT / ALPHA
        // Regex: ^[!#$%&'*+-.^_`|~0-9A-Za-z]+$
        // Compile once for performance
        final Pattern TOKEN_PATTERN = Pattern.compile("^[!#$%&'*+-.^_`|~0-9A-Za-z]+$");
        return TOKEN_PATTERN.matcher(str).matches();
    }

