/**
 * DefaultURLConstructor is responsible for determining the forward page
 * based on the incoming request. The original implementation simply
 * returned {@link HttpServletRequest#getPathInfo()}, which is unsafe
 * because it allows arbitrary path traversal and injection of malicious
 * values. The patched implementation validates and sanitizes the
 * path before returning it, ensuring that only legitimate JSP page
 * names are accepted.
 */
public class DefaultURLConstructor implements URLConstructor {

    // Regular expression that matches a safe JSP filename:
    //   • Only alphanumeric characters, underscores, or hyphens
    //   • Must end with ".jsp"
    private static final String SAFE_JSP_PATTERN = "^[A-Za-z0-9_\\-]+\\.jsp$";

    // Default page to forward to when no valid path is supplied
    private static final String DEFAULT_PAGE = "Index.jsp";

    // other methods

    /**
     * Returns the name of the JSP page to forward to. The method performs
     * strict validation to prevent path‑traversal or arbitrary file access.
     *
     * @param request the HTTP request that triggered this page
     * @return a sanitized JSP page name, or {@code DEFAULT_PAGE} if none is provided
     * @throws IllegalArgumentException if the supplied path is invalid
     */
    @Override
    public String getForwardPage(HttpServletRequest request) {
        String pathInfo = request.getPathInfo();

        // If no path info is supplied, fall back to a safe default
        if (pathInfo == null || pathInfo.trim().isEmpty()) {
            return DEFAULT_PAGE;
        }

        // Strip leading slash that getPathInfo() always provides
        String normalized = pathInfo.startsWith("/") ? pathInfo.substring(1) : pathInfo;

        // Reject any path containing directory traversal sequences or additional slashes
        if (normalized.contains("..") || normalized.contains("/") || normalized.contains("\\")) {
            throw new IllegalArgumentException("Invalid path: potential path traversal attempt");
        }

        // Enforce a whitelist pattern for allowed JSP filenames
        if (!normalized.matches(SAFE_JSP_PATTERN)) {
            throw new IllegalArgumentException("Invalid path: unexpected format");
        }

        return normalized;
    }

