import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import org.apache.commons.compress.archivers.ArchiveEntry;

/**
 * Utility class that safely expands archive entries into a target directory.
 */
public class Expander {

    // other methods ...

    /**
     * Expands all readable entries from the supplied {@link ArchiveEntrySupplier} into the
     * {@code targetDirectory}.  The implementation performs rigorous path validation to
     * prevent path‑traversal attacks.  Each entry name is normalised, checked for
     * absolute paths, and verified to stay within the target directory using canonical
     * paths.  Directory creation is performed via {@link Files#createDirectories}.
     *
     * @param supplier        provides the next readable entry
     * @param writer          writes the entry data to an {@link OutputStream}
     * @param targetDirectory the root directory where entries will be extracted
     * @throws IOException if a path traversal attempt is detected or I/O fails
     */
    private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
        // Resolve the canonical path of the target directory once
        Path canonicalTargetDir = targetDirectory.getCanonicalFile().toPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            String rawName = nextEntry.getName();

            // Reject empty or null entry names
            if (rawName == null || rawName.trim().isEmpty()) {
                throw new IOException("Entry name is empty or null");
            }

            // Normalise separators to forward slash for consistency
            String normalizedName = rawName.replace('\\', '/');

            // Reject absolute paths (starting with '/' or a drive letter on Windows)
            if (Paths.get(normalizedName).isAbsolute()) {
                throw new IOException("Entry name is absolute: " + rawName);
            }

            // Resolve the entry against the target directory and normalise
            Path entryPath = canonicalTargetDir.resolve(normalizedName).normalize();

            // Ensure the resulting path is still under the target directory
            if (!entryPath.startsWith(canonicalTargetDir)) {
                throw new IOException("expanding " + rawName + " would create file outside of " + targetDirectory);
            }

            File f = entryPath.toFile();

            if (nextEntry.isDirectory()) {
                if (!f.isDirectory() && !f.mkdirs()) {
                    throw new IOException("failed to create directory " + f);
                }
            } else {
                // Ensure parent directories exist
                File parent = f.getParentFile();
                if (parent != null && !parent.isDirectory() && !parent.mkdirs()) {
                    throw new IOException("failed to create directory " + parent);
                }

                // Write the file contents
                try (OutputStream o = Files.newOutputStream(entryPath)) {
                    writer.writeEntryDataTo(nextEntry, o);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods ...
}
