import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InvalidObjectException;
import java.io.ObjectInputStream;
import java.io.OutputStream;
import org.apache.commons.fileupload.FileItem;
import org.apache.commons.io.IOUtils;

/**
 * A disk-based implementation of {@link FileItem}.  The class is
 * serializable and therefore must guard against maliciously crafted
 * serialized instances.  The {@code readObject} method has been
 * hardened to validate the file name and to use safe I/O patterns.
 */
public class DiskFileItem implements FileItem {

    private byte[] cachedContent;
    private File dfosFile;
    private String fileName;   // assumed to exist – used for validation

    // other methods omitted for brevity

    /**
     * Reads the state of this object during deserialization.
     *
     * @param in The stream from which the state should be read.
     *
     * @throws IOException              if an error occurs.
     * @throws ClassNotFoundException   if class cannot be found.
     * @throws InvalidObjectException  if the deserialized data is invalid.
     */
    private void readObject(ObjectInputStream in)
            throws IOException, ClassNotFoundException {

        // Perform the default deserialization first
        in.defaultReadObject();

        // Validate the file name to prevent NULL‑byte or path‑traversal attacks
        if (fileName == null || !isValidFileName(fileName)) {
            throw new InvalidObjectException(
                    "Deserialized file name is invalid or contains forbidden characters");
        }

        // Obtain the output stream in a safe, deterministic way
        try (OutputStream output = getOutputStream()) {

            if (cachedContent != null) {
                output.write(cachedContent);
            } else {
                if (dfosFile == null || !dfosFile.exists()) {
                    throw new IOException("Temporary file missing during deserialization");
                }

                // Copy the temporary file to the target output stream
                try (FileInputStream input = new FileInputStream(dfosFile)) {
                    IOUtils.copy(input, output);
                }

                // Delete the temporary file only after a successful copy
                if (!dfosFile.delete()) {
                    // Log a warning – the file may remain on disk but
                    // the application logic will not attempt to reuse it.
                    System.err.println("Warning: failed to delete temporary file "
                            + dfosFile.getAbsolutePath());
                }
                dfosFile = null;
            }
        }

        // Clear cached content to free memory
        cachedContent = null;
    }

    /**
     * Validates a file name.  Rejects names containing null bytes,
     * absolute paths, or directory traversal sequences.
     *
     * @param name the file name to validate
     * @return true if the name is acceptable
     */
    private boolean isValidFileName(String name) {
        // Reject null bytes
        if (name.indexOf('\0') >= 0) {
            return false;
        }
        // Reject absolute paths or paths containing ".."
        if (new File(name).isAbsolute() || name.contains("..")) {
            return false;
        }
        // Allow only a limited set of characters (letters, digits, dash, underscore, dot)
        return name.matches("[A-Za-z0-9._-]+");
    }

    // other methods

    /**
     * Returns an {@link java.io.OutputStream OutputStream} that can
